class Solution:
    def countValidSequences(self, n: int, k: int) -> int:
        MOD = 10**9 + 7

        def comb(n, r):
            if r < 0 or r > n:
                return 0
            if r == 0 or r == n:
                return 1
            if r > n // 2:
                r = n - r

            numerator = 1
            denominator = 1
            for i in range(r):
                numerator = numerator * (n - i) % MOD
                denominator = denominator * (i + 1) % MOD

            return numerator * pow(denominator, MOD - 2, MOD) % MOD

        total = comb(n - 1, k - 1)

        if (n - k) % 2 == 0 and n >= k:
            m = (n - k) // 2
            odd_sequences = comb(m + k - 1, k - 1)
        else:
            odd_sequences = 0

        return (total - odd_sequences) % MOD

