    def minInversions(self, words: list[str], target: list[int]) -> int:
        n = len(words)

        # Build position mapping
        pos = [0] * n
        for i in range(n):
            pos[target[i]] = i

        # Build prefix tree
        class TreeNode:
            def __init__(self):
                self.children = {}
                self.word_index = -1
                self.subtree_indices = []

