            indices = []
            if node.word_index != -1:
                indices.append(node.word_index)
            for child in node.children.values():
                indices.extend(get_subtree_indices(child))
            node.subtree_indices = indices
            return indices

        get_subtree_indices(root)

        # Optimized count using prefix sums / Fenwick tree approach
        # For counting pairs (a, b) with a in list1, b in list2, pos[a] > pos[b]:
        # We can iterate through list2 and for each element, count how many elements in list1
        # have pos > pos[b]. This is equivalent to: |{a in list1 : pos[a] > pos[b]}|

        def count_inversions_between(list1, list2):
            """Count pairs (a, b) with a in list1, b in list2, pos[a] > pos[b]"""
            # Get sorted positions of list1
            pos_list1 = sorted([pos[a] for a in list1])
            count = 0
            for b in list2:
                p = pos[b]
                # Count elements in pos_list1 that are > p
                # Use binary search
                import bisect
                idx = bisect.bisect_right(pos_list1, p)
                count += len(pos_list1) - idx
            return count

        def solve(node):
            if not node.children:
                if node.word_index != -1:
                    return 0, [node.word_index]
                else:
                    return 0, []

            children_results = []
            for char in node.children:
                child = node.children[char]
                cost, ordered_indices = solve(child)
                children_results.append((cost, ordered_indices))

            child_costs = [cr[0] for cr in children_results]
            child_lists = [cr[1] for cr in children_results]
            total_cost = sum(child_costs)

            def compare_lists(list1, list2):
                inv12 = count_inversions_between(list1, list2)
                inv21 = count_inversions_between(list2, list1)
                if inv12 < inv21:
                    return -1
                elif inv12 > inv21:
                    return 1
                else:
                    return 0

            from functools import cmp_to_key
            sorted_child_lists = sorted(child_lists, key=cmp_to_key(compare_lists))

            final_ordered = []
            if node.word_index != -1:
                final_ordered.append(node.word_index)

            for cl in sorted_child_lists:
                final_ordered.extend(cl)

            # Count inversions between current node and children
            if node.word_index != -1:
                for cl in sorted_child_lists:
                    for idx in cl:
                        if pos[node.word_index] > pos[idx]:
                            total_cost += 1

            # Count inversions between different children
            for i in range(len(sorted_child_lists)):
                for j in range(i + 1, len(sorted_child_lists)):
                    total_cost += count_inversions_between(sorted_child_lists[i], sorted_child_lists[j])

            return total_cost, final_ordered

        return solve(root)[0]

class Solution:
    def minPenalty(self, period: int, lights: list[int], arrivalTime: list[int]) -> int:
        # Binary search on the answer (penalty)
        # For a given penalty P, check if it's possible to assign all cars
        # such that each car has waiting time <= P

        def can_assign(P):
            """Check if it's possible to assign all cars with max waiting time <= P"""
            for t in arrivalTime:
                r = t % period
                # Car can use light i if: r < lights[i] or r >= period - P
                can_use_any_light = False
                for L in lights:
                    if r < L or r >= period - P:
                        can_use_any_light = True
                        break
                if not can_use_any_light:
                    return False
            return True

        # Binary search for minimum P
        lo, hi = 0, period - 1
        while lo < hi:
            mid = (lo + hi) // 2
            if can_assign(mid):
                hi = mid
            else:
                lo = mid + 1

        return lo

