class Solution:
    def minDays(self, n: int) -> int:
        dp = [float('inf')] * (n + 1)
        dp[0] = 0

        # Generate all triangular numbers up to n
        tri = []
        j = 1
        while True:
            t = j * (j + 1) // 2
            if t > n:
