            # Try placing '1' at current position if allowed
            if current_str == '' or current_str[-1] != '1':
                new_cost = current_cost + index
                if new_cost <= k:
                    backtrack(current_str + '1', index + 1, new_cost)

        backtrack("", 0, 0)
        return results

class Solution:
    def validSubarrays(self, nums: list[int], k: int, queries: list[list[int]]) -> list[bool]:
        n = len(nums)
        num_queries = len(queries)
        if n == 0:
            return []

        # Block size for Mo's algorithm
        block_size = int(n ** 0.5)
        if block_size == 0:
            block_size = 1

        # Store original indices of queries to place results correctly
        indexed_queries = []
        for i, (l, r) in enumerate(queries):
            indexed_queries.append((l, r, i))

        # Sort queries using Mo's order
        def mo_key(query):
            l, r, i = query
            block = l // block_size
            # For even blocks, sort r ascending; for odd blocks, sort r descending
            if block % 2 == 0:
                return (block, r)
            else:
                return (block, -r)

        indexed_queries.sort(key=mo_key)

        # Frequency array, distinct count, odd count
        # Values in nums are up to 10^5, so size 100001 is sufficient
        max_val = 100000
        freq = [0] * (max_val + 1)
        distinct_count = 0
        odd_count = 0

        def add(idx):
            nonlocal distinct_count, odd_count
            val = nums[idx]
            if freq[val] == 0:
                distinct_count += 1
            if freq[val] % 2 == 1:
                odd_count -= 1
            freq[val] += 1
            if freq[val] % 2 == 1:
                odd_count += 1

        def remove(idx):
            nonlocal distinct_count, odd_count
            val = nums[idx]
            if freq[val] % 2 == 1:
                odd_count -= 1
            freq[val] -= 1
            if freq[val] == 0:
                distinct_count -= 1
            else:
                if freq[val] % 2 == 1:
                    odd_count += 1

        left = 0
        right = -1
        ans = [False] * num_queries

        for l, r, i in indexed_queries:
            # Move right pointer
            while right < r:
                right += 1
                add(right)
            while right > r:
                remove(right)
                right -= 1

            # Move left pointer
            while left < l:
                remove(left)
                left += 1
            while left > l:
                left -= 1
                add(left)

            # Check validity
            if distinct_count == k and odd_count == 0:
                ans[i] = True
            else:
                ans[i] = False

        return ans

class Solution:
    def countValidSubarrays(self, nums: list[int], x: int) -> int:
        n = len(nums)
        count = 0

        # Precompute prefix sums to quickly calculate subarray sums
        prefix = [0] * (n + 1)
        for i in range(n):
            prefix[i + 1] = prefix[i] + nums[i]

        # For each subarray, compute the sum and check conditions
        for l in range(n):
            for r in range(l, n):
                sub_sum = prefix[r + 1] - prefix[l]

                # Get the last digit
                last_digit = sub_sum % 10

                # Get the first digit
                first_digit = int(str(sub_sum)[0])

                if first_digit == x and last_digit == x:
                    count += 1

        return count

